(async()=>{const b=await chromium.launch({executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true});try{const c=await b.newContext();await c.route('**/*',r=>new URL(r.request().url()).origin==='http://localhost:5173'?r.continue():r.abort());await c.addInitScript({content:'window.__qaInit={path:location.pathname,at:performance.now()};'});const p=await c.newPage();p.on('pageerror',e=>console.log('error',e.message));await p.goto('http://localhost:5173/');await p.getByLabel('Import file into library').setInputFiles('tests/fixtures/safari-preview/source.vdoc.json');await p.getByRole('textbox',{name:'Document body',exact:true}).waitFor();await p.getByRole('button',{name:'Print',exact:true}).click();await p.waitForTimeout(1500);for(const f of p.frames())console.log(await f.evaluate(()=>({url:location.href,init:window.__qaInit})));}finally{await b.close()}})();
